def check():
    import math
    near = lambda a, b, t=0.006: abs(a - b) < t
    # quant
    assert (1 + .061 / 2) ** 2 > (1 + .0605 / 4) ** 4 > (1 + .06 / 12) ** 12
    assert near(5000 * (1.05 ** 10 - 1) / .05 * 1.05, 66033.94, .01)
    assert near((1.2 * 110 / 120) ** .5 - 1, .0488, 1e-4) and -100 - 120 + 220 == 0
    assert near((6.5 - 3) / 7, .5) and (6.5 - 3) / 7 > (8 - 3) / 12 > (10 - 3) / 18
    assert near(.9 / (2.4 / 6), 2.25) and near(math.sqrt(.024 / 30), .0283, 1e-4)
    assert near(.048 / .142, .338, 1e-3)
    assert near(8 - 1.96 * 2, 4.08) and near(8 + 1.96 * 2, 11.92)
    # economics
    q = 1200 - 15 * 20 + .04 * 50000 + 2.5 * 12
    assert q == 2930 and near(-15 * 20 / q, -.1024, 1e-3)
    assert 40 ** 2 + 30 ** 2 + 20 ** 2 + 10 ** 2 == 3000
    assert near(50 / (1 - .75 * .8), 125)
    assert near(1.085 * 152.4, 165.35, .01) and near(1.365 * 1.0225 / 1.015, 1.3751, 1e-4)
    assert near(1.10 / 1.05 - 1, .0476, 1e-4)
    # fsa
    assert 100 * 13 + 150 * 12 == 3100 and 4700 / 400 * 250 == 2937.5
    assert 120 + 30 - 5 - 15 + 10 - 8 == 132 and near(6 * 1.5 * 2.2, 19.8)
    pv = 10000 * (1 - 1.06 ** -5) / .06
    assert near(pv, 42123.64, .01) and near(pv * 1.06 - 10000, 34651.06, .01)
    assert (1200000 - 150000) / 500000 == 2.1 and 1200000 / 600000 == 2.0
    # corporate
    npv = lambda r, c: sum(x / (1 + r) ** t for t, x in enumerate(c))
    assert near(npv(.1, [-500, 150, 200, 250, 100]), 57.78, .01) and near(npv(.1, [-500, 300, 200, 100, 50]), 47.30, .01)
    assert near(.6 * .11 + .4 * .055 * .75, .0825, 1e-6)
    assert near((1 + 2 / 98) ** (365 / 30) - 1, .279, 1e-3)
    assert near(90 / (730 / 365) + 90 / (547.5 / 365) - 57 / (547.5 / 365), 67, .01)
    # equity
    assert near(40 * .5 / .75, 26.67, .01) and near((6 + 1 - 1.2) / 20, .29)
    assert near(2180 / 2200 - 1, -.0091, 1e-4) and near(2 * 1.04 / .05, 41.6)
    d = [1.5 * 1.12 ** t for t in (1, 2, 3)]
    assert near(sum(x / 1.1 ** (i + 1) for i, x in enumerate(d)) + d[2] * 1.04 / .06 / 1.1 ** 3, 32.11, .01)
    assert near(5 / .07, 71.43, .01) and (2000 - 600 - 50 + 150) / 100 == 15
    # fixed income
    assert near(2 * (1 - 1.025 ** -10) / .025 + 100 / 1.025 ** 10, 95.62, .01)
    p0 = sum(6 / 1.05 ** t for t in range(1, 5)) + 100 / 1.05 ** 4
    assert near(p0 * 1.05 ** (1 / 3) - 2, 103.24, .01)
    assert near(5 / 1.03 + 5 / 1.035 ** 2 + 105 / 1.04 ** 3, 102.87, .01)
    assert near(1.035 ** 2 / 1.03 - 1, .04, 1e-4)
    assert near(-7.2 / 1.06 * .005 + .5 * 65 * .005 ** 2, -.0332, 1e-4)
    assert near(1.69 / .2, 8.45) and near(6.4 * 4925000 * 1e-4, 3152, .01)
    # derivatives
    assert near(50 * 1.04 ** .5, 50.99, .01) and near(54 - 52 / 1.04 ** .25, 2.51, .01)
    assert near(8 + 100 / 1.05 - 100, 3.24, .01)
    pi = (1.05 - .8) / (1.25 - .8)
    assert near(pi * 8 / 1.05, 4.23, .01) and near(.09 / 2.82, .0319, 1e-4)
    assert 50000 - 7500 - 5000 == 37500 and near((80 + 2 - 3) * 1.05, 82.95, .01)
    # alternatives and portfolio
    assert near(118 - 2 - .2 * 16 - 100, 12.8) and near(.11 - .1 * .11, .099)
    assert near(math.sqrt(.36 * .04 + .16 * .0144 + 2 * .6 * .4 * .3 * .2 * .12), .142, 1e-3)
    assert near(12 - (3 + 1.1 * 7), 1.3) and near(.07 - 2 * .01, .05) and .05 > .09 - 2 * .0225
    for k, v in TOPICS.items():
        assert len(v) == 10, k
        for q, o, x in v:
            assert len(o) == 3 and len(set(o)) == 3, q
    return True


if __name__ == "__main__":
    print(check(), sum(len(v) for v in TOPICS.values()))
